<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Pterodactyl\Models\User; use Pterodactyl\Models\ApiKey; use Illuminate\Support\Facades\DB; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Models\Dezerx\DiscordBotAlert; use Pterodactyl\Models\Dezerx\DiscordBotMember; use Pterodactyl\Services\Api\KeyCreationService; class Linker { public const KEY_MEMO = 'Discord bot'; public const PERSONAL_MEMO = 'Discord bot (your own)'; public function __construct(private KeyCreationService $keys) { } public function link(User $user, array $discord): array { $discordId = (string) ($discord['id'] ?? ''); if ($discordId === '' || !ctype_digit($discordId)) { return ['ok' => false, 'status' => 'failed', 'message' => 'Discord did not say who you are.']; } $taken = DiscordBotMember::query() ->where('discord_id', $discordId) ->where('user_id', '!=', $user->id) ->exists(); if ($taken) { return ['ok' => false, 'status' => 'taken', 'message' => 'That Discord account is already linked to a different panel account.']; } $member = DB::transaction(function () use ($user, $discord, $discordId) { $member = DiscordBotMember::query()->where('user_id', $user->id)->lockForUpdate()->first() ?? new DiscordBotMember(['user_id' => $user->id]); $member->fill([ 'discord_id' => $discordId, 'username' => mb_substr((string) ($discord['username'] ?? 'Discord user'), 0, 191), 'avatar' => is_string($discord['avatar'] ?? null) ? $discord['avatar'] : null, ]); if ($member->api_key_id === null || !ApiKey::query()->whereKey($member->api_key_id)->exists()) { $member->api_key_id = $this->issue($user, self::KEY_MEMO)->id; } $member->save(); return $member; }); return ['ok' => true, 'status' => 'connected', 'message' => 'Linked.', 'member' => $member]; } public function reissue(DiscordBotMember $member): DiscordBotMember { if ($member->api_key_id !== null && ApiKey::query()->whereKey($member->api_key_id)->exists()) { return $member; } $member->forceFill(['api_key_id' => $this->issue($member->user, self::KEY_MEMO)->id])->save(); return $member; } public function unlink(DiscordBotMember $member): void { DB::transaction(function () use ($member) { $keyId = $member->api_key_id; DiscordBotAlert::query() ->where('user_id', $member->user_id) ->whereHas('bot', fn ($query) => $query->whereNull('user_id')) ->delete(); $member->delete(); $this->revoke($keyId, $member->user_id, self::KEY_MEMO); }); } public function keyForBot(DiscordBot $bot): DiscordBot { if ($bot->isGlobal() || $bot->owner === null) { return $bot; } if ($bot->api_key_id === null || !ApiKey::query()->whereKey($bot->api_key_id)->exists()) { $bot->forceFill(['api_key_id' => $this->issue($bot->owner, self::PERSONAL_MEMO)->id])->save(); } return $bot; } public function forgetBot(DiscordBot $bot): void { DB::transaction(function () use ($bot) { $keyId = $bot->api_key_id; $owner = $bot->user_id; $bot->delete(); if ($owner !== null) { $this->revoke($keyId, $owner, self::PERSONAL_MEMO); } }); } public static function memberFor(string $discordId): ?DiscordBotMember { if ($discordId === '') { return null; } return DiscordBotMember::query()->with('user')->where('discord_id', $discordId)->first(); } private function issue(User $user, string $memo): ApiKey { return $this->keys->setKeyType(ApiKey::TYPE_ACCOUNT)->handle([ 'user_id' => $user->id, 'memo' => $memo, 'allowed_ips' => [ClientApi::LOOPBACK, '::1'], ]); } private function revoke(?int $keyId, int $userId, string $memo): void { if ($keyId === null) { return; } ApiKey::query()->whereKey($keyId)->where('user_id', $userId)->where('memo', $memo)->delete(); } } 